"}],"defects":[{"id":"D1","class":"DUS","witness_test_ids":["T02"],"reason":"The re-enrollment flag in the Verify response is recomputed from the handle version in the caller-writable request buffer when the response is built. The private value derived earlier is no longer the only source. If the buffer changes after verification, the reported flag changes too.","detector_targets":[{"path":"ta/gatekeeper_ta.c","function":"TA_Verify","lines":[706,706],"role":"effect"},{"path":"ta/gatekeeper_ta.c","function":"TA_Verify","lines":[670,670],"role":"protection"}]},{"id":"D2","class":"UDO","witness_test_ids":["T03"],"reason":"For passwords longer than 8 bytes, the first bytes of the plaintext password are copied into the flags field of the password handle after signing. The handle is returned to the caller, so the protected password appears in the output unprotected.","detector_targets":[{"path":"ta/gatekeeper_ta.c","function":"TA_CreatePasswordHandle","lines":[231,231],"role":"effect"},{"path":"ta/gatekeeper_ta.c","function":"TA_CreatePasswordHandle","lines":[222,224],"role":"protection"}]}],"tests":[{"id":"T01","purpose":"normal","targets":[],"steps":[{"op":"open","session":"s1"},{"op":"invoke","session":"s1","command_id":0,"params":[{"type":"memref_input","data":"01000000 08000000 70617373776f7264 00000000 00000000"},{"type":"memref_output","size":128},{"type":"none"},{"type":"none"}]},{"op":"invoke","session":"s1","command_id":1,"params":[{"type":"memref_input","data":"01000000 0100000000000000 3a000000 00000000000000000000 00000000000000000000 00000000000000000000 00000000000000000000 00000000000000000000 0000000000000000 08000000 70617373776f7264","inserts":[{"offset":16,"from":{"step":2,"param":1,"offset":8,"length":58}}]},{"type":"memref_output","size":128},{"type":"none"},{"type":"none"}]},{"op":"close","session":"s1"}]},{"id":"T02","purpose":"witness","targets":["D1"],"witness_step":3,"steps":[{"op":"open","session":"s1"},{"op":"invoke","session":"s1","command_id